import React from 'react';

const TABS = [
  { id:'home',      label:'Hem' },
  { id:'checkin',   label:'Check-in' },
  { id:'history',   label:'Historik' },
  { id:'breathing', label:'Andning' },
];

export default function Nav({ page, setPage }) {
  return (
    <>
      {/* Top — minimal, just brand */}
      <div style={{ fontSize:16, fontWeight:700, letterSpacing:'-0.03em', color:'#1c1917' }}>Spiral</div>
      <div />

      {/* Bottom pill nav — warm frosted */}
      <div style={{ position:'fixed', bottom:20, left:20, right:20, zIndex:100, display:'flex', height:58, background:'rgba(255,255,255,0.72)', backdropFilter:'blur(24px) saturate(1.6)', borderRadius:24, border:'1px solid rgba(255,255,255,0.9)', boxShadow:'0 8px 32px rgba(0,0,0,0.1), 0 1px 0 rgba(255,255,255,0.8) inset' }}>
        {TABS.map(tab => (
          <button key={tab.id} onClick={()=>setPage(tab.id)}
            style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:3, border:'none', background:'none', borderRadius:20, margin:4, transition:'all .25s', background: page===tab.id ? 'rgba(0,0,0,0.06)' : 'transparent', position:'relative' }}>
            <span style={{ fontSize:11, fontWeight: page===tab.id ? 600 : 400, color: page===tab.id ? '#1c1917' : 'rgba(28,25,23,0.38)', letterSpacing:'0.01em', transition:'all .25s' }}>{tab.label}</span>
            {page===tab.id && <div style={{ position:'absolute', bottom:4, width:16, height:2, borderRadius:1, background:'rgba(28,25,23,0.4)' }} />}
          </button>
        ))}
      </div>
    </>
  );
}
